/**
 * Contract test (TEST-05, CMD-13).
 *
 * Typed commands: `src/lib/bindings.ts` is generated by tauri-specta from the
 * Rust signatures (`src-tauri/src/commands/bindings.rs`), so `pnpm typecheck`
 * checks every wrapper that calls `commands.*` against the Rust argument,
 * return and error types, and the `commands::bindings` cargo test fails when
 * the checked-in file is stale.
 *
 * This file checks the remaining string-level links: every command the
 * bindings or a raw `invoke("name")` call refers to must be registered in
 * `tauri::generate_handler![...]` (`src-tauri/src/lib.rs`), and every MSW mock
 * must target a registered command.
 */
import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { commands } from "@/lib/bindings";

const ROOT = path.resolve(__dirname, "../..");
const BINDINGS = "src/lib/bindings.ts";

function readRegisteredCommands(): Set<string> {
  const lib = fs.readFileSync(path.join(ROOT, "src-tauri/src/lib.rs"), "utf8");
  const start = lib.indexOf("tauri::generate_handler![");
  expect(start, "generate_handler! not found in lib.rs").toBeGreaterThan(-1);
  const end = lib.indexOf("])", start);
  const body = lib
    .slice(start + "tauri::generate_handler![".length, end)
    .replace(/\/\/[^\n]*/g, "")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/#\[[^\]]*\]/g, "");
  const names = body
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean)
    .map((entry) => entry.split("::").pop()!.trim());
  return new Set(names);
}

function listSourceFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...listSourceFiles(full));
    } else if (
      /\.(ts|tsx)$/.test(entry.name) &&
      !/\.test\.tsx?$/.test(entry.name)
    ) {
      out.push(full);
    }
  }
  return out;
}

// `invoke("cmd")`, `invoke<T>("cmd")`, `invoke<Array<T>>(\n "cmd", ...)`.
const INVOKE_RE = /\binvoke\s*(?:<[\s\S]*?>)?\(\s*["'`]([A-Za-z0-9_]+)["'`]/g;
// Wrapper call sites: `commands.someCommand(`.
const COMMANDS_CALL_RE = /\bcommands\.([A-Za-z0-9_]+)\(/g;

function readBindingCommands(): Map<string, string> {
  const text = fs.readFileSync(path.join(ROOT, BINDINGS), "utf8");
  const byAccessor = new Map<string, string>();
  for (const match of text.matchAll(
    /^async (\w+)\([\s\S]*?TAURI_INVOKE\(\s*"([A-Za-z0-9_]+)"/gm,
  )) {
    byAccessor.set(match[1], match[2]);
  }
  return byAccessor;
}

function readInvokedCommands(): Map<string, string[]> {
  const invoked = new Map<string, string[]>();
  const bindings = readBindingCommands();
  const add = (name: string, rel: string) => {
    const files = invoked.get(name) ?? [];
    if (!files.includes(rel)) files.push(rel);
    invoked.set(name, files);
  };
  for (const file of listSourceFiles(path.join(ROOT, "src"))) {
    const rel = path.relative(ROOT, file);
    if (rel === BINDINGS) continue;
    const text = fs.readFileSync(file, "utf8");
    for (const match of text.matchAll(INVOKE_RE)) add(match[1], rel);
    for (const match of text.matchAll(COMMANDS_CALL_RE)) {
      const name = bindings.get(match[1]);
      if (name) add(name, rel);
    }
  }
  return invoked;
}

function readMswHandlerCommands(): string[] {
  const text = fs.readFileSync(
    path.join(ROOT, "tests/msw/handlers.ts"),
    "utf8",
  );
  return [...text.matchAll(/\$\{TAURI_ENDPOINT\}\/([A-Za-z0-9_]+)`/g)].map(
    (m) => m[1],
  );
}

describe("Tauri command registry contract", () => {
  const registered = readRegisteredCommands();
  const invoked = readInvokedCommands();
  const bindingCommands = readBindingCommands();

  it("parses a plausible number of registered commands", () => {
    expect(registered.size).toBeGreaterThan(200);
    expect(registered.has("switch_provider")).toBe(true);
    expect(registered.has("save_settings")).toBe(true);
  });

  it("parses the generated bindings", () => {
    expect(bindingCommands.size).toBeGreaterThan(100);
    // Every accessor the scan found exists on the runtime `commands` object.
    for (const accessor of bindingCommands.keys()) {
      expect(
        typeof (commands as Record<string, unknown>)[accessor],
        accessor,
      ).toBe("function");
    }
  });

  it("every command in the generated bindings is registered in generate_handler!", () => {
    const missing = [...bindingCommands.values()]
      .filter((name) => !registered.has(name))
      .sort();
    expect(missing).toEqual([]);
  });

  it("finds the frontend call sites (raw invoke and generated commands)", () => {
    expect(invoked.size).toBeGreaterThan(200);
    // Sanity: the API wrappers are covered by the scan.
    expect(
      invoked.get("switch_provider")?.some((f) => f.startsWith("src/lib/api/")),
    ).toBe(true);
  });

  it("every command invoked from src/ is registered in generate_handler!", () => {
    const missing = [...invoked.entries()]
      .filter(([name]) => !registered.has(name))
      .map(([name, files]) => `${name} (invoked from ${files.join(", ")})`)
      .sort();
    expect(missing).toEqual([]);
  });

  it("every MSW handler mocks a registered command", () => {
    const handlers = readMswHandlerCommands();
    expect(handlers.length).toBeGreaterThan(0);
    const phantom = handlers.filter((name) => !registered.has(name)).sort();
    expect(phantom).toEqual([]);
  });

  it("src/lib/api wrappers reach typed commands through the bindings", () => {
    // A raw invoke of a command that has a generated binding bypasses the
    // typed contract; call `commands.*` instead.
    const typed = new Set(bindingCommands.values());
    const bypass: string[] = [];
    for (const file of listSourceFiles(path.join(ROOT, "src/lib/api"))) {
      const text = fs.readFileSync(file, "utf8");
      for (const match of text.matchAll(INVOKE_RE)) {
        if (typed.has(match[1])) {
          bypass.push(`${match[1]} (${path.relative(ROOT, file)})`);
        }
      }
    }
    expect(bypass.sort()).toEqual([]);
  });
});
